['int, Tuple[float, float]],\n    routes: List[List[int]],\n    depot: int = 1,\n    route_names: List[str] = None\n) -> List[RouteSegment]:\n    "', '\n    Convert CVRP solution to RouteSegment list for GPX export.\n    \n    Args:\n        problem_coords: Dictionary mapping node IDs to (lat, lon) coordinates\n        routes: List of routes, each route is a list of node IDs\n        depot: Depot node ID\n        route_names: Optional list of names for each route\n        \n    Returns:\n        List of RouteSegment objects for GPX export\n    "', '\n    segments: List[RouteSegment] = []\n    \n    for i, route in enumerate(routes):\n        if not route:\n            continue\n            \n        # Create waypoints for each customer\n        waypoints = []\n        \n        # Add depot as start waypoint\n        depot_lat, depot_lon = problem_coords[depot]\n        waypoints.append(Waypoint(depot_lat, depot_lon, name="Depot Start', 'Add customer waypoints\n        for node_id in route:\n            lat, lon = problem_coords[node_id]\n            waypoints.append(Waypoint(lat, lon, name=f"Customer {node_id}', 'Add depot as end waypoint\n        waypoints.append(Waypoint(depot_lat, depot_lon, name="Depot End', 'Create track points (full route including start and end at depot)\n        track = []\n        \n        # Start at depot\n        track.append((depot_lat, depot_lon))\n        \n        # Add customer locations\n        for node_id in route:\n            lat, lon = problem_coords[node_id]\n            track.append((lat, lon))\n            \n        # Return to depot\n        track.append((depot_lat, depot_lon))\n        \n        # Create route name\n        name = route_names[i] if route_names and i < len(route_names) else f"Vehicle {i+1}', 'segments.append(\n            RouteSegment(\n                track=track,\n                waypoints=waypoints,\n                name=name\n            )\n        )\n    \n    return segments\n\n\ndef two_opt_solution_to_gpx_segments(\n    problem_coords: Dict[int, Tuple[float, float]],\n    routes: List[List[int]],\n    depot: int = 1,\n    route_names: List[str] = None\n) -> List[RouteSegment]:\n    "', '\n    Convert 2-Opt improved CVRP solution to RouteSegment list for GPX export.\n    \n    This is essentially the same as cvrp_solution_to_gpx_segments since 2-Opt\n    just improves the ordering of nodes in each route.\n    \n    Args:\n        problem_coords: Dictionary mapping node IDs to (lat, lon) coordinates\n        routes: List of routes after 2-Opt improvement, each route is a list of node IDs\n        depot: Depot node ID\n        route_names: Optional list of names for each route\n        \n    Returns:\n        List of RouteSegment objects for GPX export\n    "', '\n    return cvrp_solution_to_gpx_segments(problem_coords, routes, depot, route_names)']